insert into public.experiences (slug, name, client, description, base_url, status, show_in_showcase, type)
values (
  'unipol-cinque-domande',
  'Cinque domande',
  'Unipol',
  'Le cinque domande fatte dal cliente nel programma high-touch su CX Enterprise Coworker, ognuna risposta oggi e con Coworker, e ogni voce marcata per livello di fonte.',
  '/experience-design-factory/unipol-cinque-domande/',
  'live',
  false,
  'playbook'
)
on conflict (slug) do update
   set name             = excluded.name,
       client           = excluded.client,
       description      = excluded.description,
       base_url         = excluded.base_url,
       status           = excluded.status,
       show_in_showcase = excluded.show_in_showcase,
       type             = excluded.type,
       updated_at       = now();
